import gzip,urllib.request,heapq,re,subprocess,os,tempfile
PEAK='https://www.encodeproject.org/files/ENCFF717TCQ/@@download/ENCFF717TCQ.bed.gz'
SNP='https://hgdownload.soe.ucsc.edu/goldenPath/hg38/database/snp151Common.txt.gz'
BASE=set('ACGT')
def ok(obs):
 a=[x.upper() for x in re.split(r'[/,]',obs) if x]
 return len(set(a))==2 and all(x in BASE for x in a)
def merge(iv):
 out=[]
 for s,e in sorted(iv):
  if not out or s>out[-1][1]: out.append([s,e])
  elif e>out[-1][1]: out[-1][1]=e
 return out
def contains(x,iv):
 import bisect
 # simple
 return any(s<=x<e for s,e in iv)
peaks=[]
with gzip.GzipFile(fileobj=urllib.request.urlopen(PEAK)) as fh:
 for i,raw in enumerate(fh,1):
  p=raw.decode().rstrip('\\n').split('\\t')
  peaks.append((float(p[8]),i,p))
scenarios={
 'top1000_genome': [p for q,i,p in sorted(peaks,key=lambda x:(-x[0],x[1]))[:1000] if p[0]=='chr1'],
 'top1000_chr1': [p for q,i,p in sorted([x for x in peaks if x[2][0]=='chr1'], key=lambda x:(-x[0],x[1]))[:1000]],
 'all_chr1': [p for q,i,p in peaks if p[0]=='chr1'],
}
for name,plist in scenarios.items():
 iv=merge((int(p[1]),int(p[2])) for p in plist)
 c=[]
 with gzip.GzipFile(fileobj=urllib.request.urlopen(SNP)) as fh:
  for raw in fh:
   f=raw.decode().rstrip('\\n').split('\\t')
   if len(f)>=10 and f[1]=='chr1' and ok(f[9]) and contains(int(f[2]),iv):
    c.append(int(f[2]))
 print(name,'peaks',len(plist),'merged',len(iv),'ucsc',len(set(c)))
 for offset in [0,1,2]:
  fn=f'tmp_{name}_{offset}.regions'
  with open(fn,'w') as out:
   for s in sorted(set(c)):
    out.write(f'chr1\\t{s+offset}\\t{s+offset}\\n')
  cmd=['bcftools','view','-R',fn,'-i','strlen(REF)=1 && REF~\""'^[ACGT]$" && strlen(ALT)=1 && ALT~"''^[ACGT]$"'"','https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/working/20201028_3202_raw_GT_with_annot/20201028_CCDG_14151_B01_GRM_WGS_2020-08-05_chr1.recalibrated_variants.vcf.gz','-H']
  res=subprocess.run(cmd,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
  n=sum(1 for line in res.stdout.splitlines() if line)
  print(' offset',offset,'vcf',n,'err',res.stderr.splitlines()[:1])
PY"

